module signal_generator (
    input clk, rst_n,
    output reg [4:0] wave
);
// Add your code here
// State and waveform generation
reg [1:0] state;
// Sequential logic for state and waveform updates
always @(posedge clk or negedge rst_n) begin
    if (~rst_n) begin
        state <= 2'b00;
        wave <= 5'b0;
    end else begin
        case(state)
            2'b00: begin
                if(wave == 5'b11111) begin
                    state <= 2'b01;
                end else begin
                    wave <= wave + 1;
                end
            end

            2'b01: begin
                if(wave == 5'b00000) begin
                    state <= 2'b00;
                end else begin
                    wave <= wave - 1;
                end
            end
        endcase
    end
end
endmodule
